        #4;
        areset = 0;
        #1;
        if (dut.state !== 2'b01) begin
            $display("Reset recovery Fail: State is not A, got %b", dut.state);
            errors = errors + 1;
        end

        // Check sequence again after reset: A -> x=1 (z=1) -> B -> x=0 (z=1) -> B -> x=0 (z=1)
        check_transition(1, 1);
        check_transition(0, 1);
        check_transition(0, 1);

        // Test 5: Corner Case - Illegal State Recovery
